using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private static readonly Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly InfrastructureAssembly = typeof(HttpPaymentGateway).Assembly;

    // Technical details (I/O, HTTP, serialization, ...) belong in Infrastructure only.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Text.Json", "System.Data",
        "System.Diagnostics.Process", "Microsoft.Extensions", "Newtonsoft",
    ];

    private static readonly string[] InfrastructureNamespaces = ["PaymentAuthorization.Infrastructure"];

    public static TheoryData<string> Layers => new() { "Domain", "Application" };

    private static Assembly Resolve(string layer) => layer == "Domain" ? DomainAssembly : ApplicationAssembly;

    [Theory]
    [MemberData(nameof(Layers))]
    public void Layer_does_not_depend_on_technical_details(string layer)
    {
        var result = Types.InAssembly(Resolve(layer)).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces).GetResult();
        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Theory]
    [MemberData(nameof(Layers))]
    public void Layer_does_not_depend_on_infrastructure(string layer)
    {
        var result = Types.InAssembly(Resolve(layer)).ShouldNot().HaveDependencyOnAny(InfrastructureNamespaces).GetResult();
        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_depend_on_application()
    {
        var result = Types.InAssembly(DomainAssembly).ShouldNot().HaveDependencyOn("PaymentAuthorization.Application").GetResult();
        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Layers_are_non_empty()
    {
        Assert.NotEmpty(Types.InAssembly(DomainAssembly).GetTypes());
        Assert.NotEmpty(Types.InAssembly(ApplicationAssembly).GetTypes());
        Assert.NotEmpty(Types.InAssembly(InfrastructureAssembly).GetTypes());
    }

    private static string Describe(TestResult result) =>
        "Layer violation in: " + string.Join(", ", result.FailingTypeNames ?? []);
}
